import React, { useState } from 'react';
import styled from 'styled-components';
import { AnimatePresence, motion } from 'framer-motion';
import Modal from 'react-modal';

Modal.setAppElement('#root');

const AlbumWrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 20px;
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
`;

const Title = styled.h1`
  color: white;
  margin-bottom: 40px;
  font-size: 2.5rem;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
`;

const BookContainer = styled.div`
  perspective: 2000px;
  width: 600px;
  height: 450px;
  position: relative;
`;

const Book = styled.div`
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
`;

const Page = styled(motion.div)`
  position: absolute;
  width: 100%;
  height: 100%;
  transform-origin: left center;
  transform-style: preserve-3d;
  cursor: pointer;
`;

const PageFace = styled.div`
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
`;

const FrontFace = styled(PageFace)`
  background: white;
`;

const BackFace = styled(PageFace)`
  background: white;
  transform: rotateY(180deg);
`;

const Photo = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
`;

const PageNumber = styled.div`
  position: absolute;
  bottom: 10px;
  right: 15px;
  color: #666;
  font-size: 14px;
`;

const NavigationButtons = styled.div`
  display: flex;
  gap: 20px;
  margin-top: 30px;
`;

const NavButton = styled.button`
  padding: 12px 30px;
  font-size: 16px;
  border: none;
  border-radius: 25px;
  background: white;
  color: #667eea;
  cursor: pointer;
  font-weight: bold;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  transition: all 0.3s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
  }
`;

const photoPairs = [
  {
    left: 'https://picsum.photos/seed/album1/600/450',
    right: 'https://picsum.photos/seed/album2/600/450',
  },
  {
    left: 'https://picsum.photos/seed/album3/600/450',
    right: 'https://picsum.photos/seed/album4/600/450',
  },
  {
    left: 'https://picsum.photos/seed/album5/600/450',
    right: 'https://picsum.photos/seed/album6/600/450',
  },
  {
    left: 'https://picsum.photos/seed/album7/600/450',
    right: 'https://picsum.photos/seed/album8/600/450',
  },
];

function App() {
  const [currentPage, setCurrentPage] = useState(0);
  const [selectedPhoto, setSelectedPhoto] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const totalPages = photoPairs.length;

  const goToNextPage = () => {
    if (currentPage < totalPages) {
      setCurrentPage(currentPage + 1);
    }
  };

  const goToPrevPage = () => {
    if (currentPage > 0) {
      setCurrentPage(currentPage - 1);
    }
  };

  const openModal = (photo) => {
    setSelectedPhoto(photo);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setTimeout(() => setSelectedPhoto(null), 300);
  };

  return (
    <AlbumWrapper>
      <Title>Digital Photo Album</Title>

      <BookContainer>
        <Book>
          {photoPairs.map((pair, index) => {
            const isFlipped = index < currentPage;

            return (
              <Page
                key={index}
                initial={false}
                animate={{
                  rotateY: isFlipped ? -180 : 0,
                  zIndex: totalPages - index,
                }}
                transition={{
                  duration: 0.8,
                  ease: [0.2, 0.8, 0.2, 1],
                }}
                style={{ zIndex: totalPages - index }}
              >
                <FrontFace>
                  <Photo
                    src={pair.right}
                    alt={`Page ${index + 1} right`}
                    onClick={() => openModal(pair.right)}
                  />
                  <PageNumber>{index + 1}</PageNumber>
                </FrontFace>
                <BackFace>
                  <Photo
                    src={pair.left}
                    alt={`Page ${index + 1} left`}
                    onClick={() => openModal(pair.left)}
                  />
                  <PageNumber>{index}</PageNumber>
                </BackFace>
              </Page>
            );
          })}
        </Book>
      </BookContainer>

      <NavigationButtons>
        <NavButton onClick={goToPrevPage} disabled={currentPage === 0}>
          Previous
        </NavButton>
        <NavButton onClick={goToNextPage} disabled={currentPage === totalPages}>
          Next
        </NavButton>
      </NavigationButtons>

      <Modal
        isOpen={isModalOpen}
        onRequestClose={closeModal}
        style={{
          overlay: {
            backgroundColor: 'rgba(0, 0, 0, 0.95)',
            zIndex: 1000,
          },
          content: {
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            border: 'none',
            borderRadius: 0,
            background: 'transparent',
            overflow: 'hidden',
            padding: 0,
          },
        }}
      >
        <AnimatePresence>
          {selectedPhoto && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={closeModal}
              style={{
                position: 'relative',
                width: '100%',
                height: '100%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <motion.img
                src={selectedPhoto}
                alt="Selected"
                initial={{ scale: 0.5, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.5, opacity: 0 }}
                transition={{ type: 'spring', duration: 0.5 }}
                onClick={(e) => e.stopPropagation()}
                style={{
                  maxWidth: '95%',
                  maxHeight: '95%',
                  objectFit: 'contain',
                  borderRadius: '10px',
                  boxShadow: '0 20px 60px rgba(0, 0, 0, 0.5)',
                }}
              />
              <button
                onClick={closeModal}
                style={{
                  position: 'absolute',
                  top: '20px',
                  right: '20px',
                  background: 'white',
                  border: 'none',
                  borderRadius: '50%',
                  width: '45px',
                  height: '45px',
                  fontSize: '24px',
                  cursor: 'pointer',
                  boxShadow: '0 4px 15px rgba(0, 0, 0, 0.3)',
                  zIndex: 10,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                ×
              </button>
            </motion.div>
          )}
        </AnimatePresence>
      </Modal>
    </AlbumWrapper>
  );
}

export default App;
